const H={'apikey':K,'Authorization':'Bearer '+K,'Content-Type':'application/json'};let token='',users={},busy=false;
function session(){try{return JSON.parse(sessionStorage.getItem('rc_music_dj_session_v1')||localStorage.getItem('rc_music_dj_session_v1')||'null')}catch{return null}}
async function loadUsers(){const s=session();if(!s?.token)return;token=s.token;try{const r=await fetch(U+'/rest/v1/rpc/admin_list_djs',{method:'POST',headers:H,body:JSON.stringify({p_token:token})});const rows=await r.json();if(Array.isArray(rows)){users={};rows.forEach(x=>users[String(x.email||'').toLowerCase()]=x);mount();}}catch{}}
function cardFor(input){let p=input;for(let i=0;i<8&&p;i++,p=p.parentElement)if(p.querySelector?.('button[aria-label="Eliminar usuario DJ"]'))return p;return null}
