function fmt(v){if(!v)return '—';try{return new Intl.DateTimeFormat('es-PE',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v))}catch{return String(v)}}
function el(tag,text,style){const x=document.createElement(tag);if(text!==undefined)x.textContent=text;if(style)x.style.cssText=style;return x}
async function openEvents(u){if(document.getElementById('rc-admin-events-page'))return;const page=el('div');page.id='rc-admin-events-page';page.style.cssText='position:fixed;inset:0;z-index:13000;overflow:auto;background:linear-gradient(150deg,#080914 0%,#111126 55%,#160817 100%);color:#fff;padding:20px 14px 42px;';const wrap=el('div');wrap.style.cssText='width:min(100%,980px);margin:0 auto;';const head=el('div');head.style.cssText='display:flex;align-items:flex-start;justify-content:space-between;gap:15px;margin-bottom:18px;';const title=el('div');title.append(el('p','Centro de gestión', 'margin:0 0 5px;color:#6cefff;font-size:12px;font-weight:900;text-transform:uppercase;letter-spacing:.14em;'),el('h1','Eventos de '+(u.display_name||u.email),'margin:0;font-size:clamp(23px,4vw,34px);font-weight:900;'),el('p',u.email,'margin:6px 0 0;color:rgba(255,255,255,.55);font-size:13px;'));const close=el('button','Volver');close.type='button';close.style.cssText='border:1px solid rgba(255,255,255,.2);border-radius:12px;background:rgba(255,255,255,.06);color:#fff;padding:10px 14px;font-weight:900;cursor:pointer;';close.onclick=()=>page.remove();head.append(title,close);const toolbar=el('div');toolbar.style.cssText='display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin-bottom:15px;padding:13px;border:1px solid rgba(0,229,255,.2);border-radius:16px;background:rgba(0,229,255,.06);';const allLabel=el('label');allLabel.style.cssText='display:flex;align-items:center;gap:8px;font-size:13px;font-weight:900;cursor:pointer;';const all=el('input');all.type='checkbox';all.style.cssText='width:17px;height:17px;accent-color:#00e5ff;';allLabel.append(all,el('span','Seleccionar todos'));const delSelected=el('button','Eliminar seleccionados');delSelected.type='button';delSelected.style.cssText='border:1px solid rgba(255,55,211,.55);border-radius:10px;background:rgba(255,55,211,.12);color:#fff;padding:9px 12px;font-weight:900;cursor:pointer;';const delAll=el('button','Eliminar todos');delAll.type='button';delAll.style.cssText='border:1px solid rgba(255,80,100,.7);border-radius:10px;background:rgba(255,60,80,.12);color:#ffb8c0;padding:9px 12px;font-weight:900;cursor:pointer;';const status=el('span','');status.style.cssText='font-size:12px;color:#6cefff;';toolbar.append(allLabel,delSelected,delAll,status);const list=el('div');list.style.cssText='display:grid;gap:12px;';wrap.append(head,toolbar,list);page.appendChild(wrap);document.body.appendChild(page);let events=[],selected=new Set();async function refresh(){status.textContent='Cargando eventos…';try{const r=await fetch(U+'/rest/v1/rpc/admin_list_dj_events',{method:'POST',headers:H,body:JSON.stringify({p_token:token,p_dj_id:u.id})});if(!r.ok)throw Error();events=await r.json();if(!Array.isArray(events))events=[];selected=new Set([...selected].filter(id=>events.some(x=>x.id===id)));status.textContent=events.length?`${events.length} evento${events.length===1?'':'s'}`:'No hay eventos creados.';render();}catch{status.textContent='No se pudo cargar el historial.';}}
function render(){list.replaceChildren();all.checked=events.length>0&&selected.size===events.length;all.indeterminate=selected.size>0&&selected.size<events.length;delSelected.disabled=selected.size===0;delSelected.style.opacity=selected.size?'1':'.45';delAll.disabled=!events.length;delAll.style.opacity=events.length?'1':'.45';events.forEach(e=>{const article=el('article');article.style.cssText='border:1px solid rgba(255,255,255,.12);border-radius:17px;background:rgba(255,255,255,.04);padding:15px;';const top=el('div');top.style.cssText='display:flex;align-items:flex-start;gap:11px;';const cb=el('input');cb.type='checkbox';cb.checked=selected.has(e.id);cb.style.cssText='margin-top:4px;width:17px;height:17px;accent-color:#00e5ff;';cb.onchange=()=>{cb.checked?selected.add(e.id):selected.delete(e.id);render()};const main=el('div');main.style.cssText='min-width:0;flex:1;';const name=el('h2',e.name||'Evento sin nombre','margin:0;color:#fff;font-size:17px;font-weight:900;');const meta=el('p',`${e.code||'Sin código'} · Creado: ${fmt(e.created_at)}`,'margin:5px 0 0;color:rgba(255,255,255,.58);font-size:12px;');const detail=el('p',`Última actividad: ${fmt(e.finalized_at||e.created_at)} · ${e.request_count||0} pedido${Number(e.request_count)===1?'':'s'}`,'margin:5px 0 0;color:#6cefff;font-size:12px;font-weight:800;');main.append(name,meta,detail);top.append(cb,main);const view=el('button',`Ver pedidos (${e.request_count||0})`);view.type='button';view.style.cssText='border:1px solid rgba(108,239,255,.35);border-radius:9px;background:rgba(108,239,255,.08);color:#6cefff;padding:7px 9px;font-size:11px;font-weight:900;cursor:pointer;white-space:nowrap;';const req=el('div');req.style.cssText='display:none;margin:13px 0 0 28px;border-top:1px solid rgba(255,255,255,.1);padding-top:10px;';(e.requests||[]).forEach(r=>{const p=el('p',`${r.title||'Sin título'}${r.artist?' · '+r.artist:''} — ${r.status||'sin estado'} · ${fmt(r.created_at)}`,'margin:0 0 7px;color:rgba(255,255,255,.7);font-size:12px;');req.appendChild(p)});view.onclick=()=>{req.style.display=req.style.display==='none'?'block':'none';view.textContent=req.style.display==='none'?`Ver pedidos (${e.request_count||0})`:'Ocultar pedidos'};article.append(top,view,req);list.appendChild(article)})}
all.onchange=()=>{selected=all.checked?new Set(events.map(e=>e.id)):new Set();render()};delSelected.onclick=()=>remove([...selected]);delAll.onclick=()=>remove(null);async function remove(ids){if(busy)return;if(ids&&ids.length===0)return;if(!window.confirm(ids?'¿Eliminar los eventos seleccionados y todos sus pedidos?':'¿Eliminar todos los eventos de este usuario y todos sus pedidos?'))return;busy=true;status.textContent='Eliminando…';try{const r=await fetch(U+'/rest/v1/rpc/admin_delete_dj_events',{method:'POST',headers:H,body:JSON.stringify({p_token:token,p_dj_id:u.id,p_event_ids:ids})});if(!r.ok)throw Error();selected=new Set();await refresh();}catch{status.textContent='No se pudieron eliminar los eventos.'}finally{busy=false}}await refresh()}
new MutationObserver(()=>mount()).observe(document.documentElement,{childList:true,subtree:true});loadUsers();setInterval(loadUsers,5000);
